ground:#f5f8fc;color:#334155;font-weight:600}.sample-table-wrap tbody tr:hover{background:#f8fbff}.sample-pagination{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0;font-size:12px;font-variant-numeric:tabular-nums}.sample-pagination>span{margin-right:auto}.sample-pagination button{background:white;border:1px solid #ccdae9;border-radius:5px;padding:6px 12px;color:#245c99;min-height:36px;cursor:pointer;transition:background-color .15s ease,border-color .15s ease}.sample-pagination button:hover:not(:disabled){background:#f0f7ff;border-color:#93c5fd}.sample-pagination button:disabled{opacity:.5;cursor:default}.sample-staffing{margin:14px 0}.sample-staffing div{display:flex;justify-content:space-between;gap:18px;padding:12px 0;border-bottom:1px solid #e5ebf3;font-size:13px}.sample-staffing dt{color:#65778d;min-width:100px}.sample-staffing dd{margin:0;text-align:right;overflow-wrap:anywhere;min-width:0;font-weight:500;color:#1e293b;font-variant-numeric:tabular-nums}@media(max-width:760px){.sample-panels{grid-template-columns:1fr}.sample-panel{padding:14px}.sample-pagination button{min-height:44px}.sample-filter{min-height:44px}}
</style>
